package main

const assistantHTML = `<details id="assistant-panel" class="card"><summary>App Assistant</summary><p>選擇你的模型，讓它查詢資料、研究與準備變更。</p><form id="assistant-config-form"><label>Assistant 模型<select id="assistant-target" required></select></label><button>保存 Assistant 模型</button><p>模型須已確認工具呼叫能力。</p></form><div class="toolbar"><label>Assistant 對話<select id="assistant-thread"><option value="">新對話</option></select></label><button id="assistant-new" type="button" class="ghost">新的 Assistant 對話</button></div><div id="assistant-chat" class="chat" role="log" aria-live="polite"></div><form id="assistant-form"><label>交給 Assistant 的工作<textarea id="assistant-prompt" maxlength="12000" required placeholder="例如：查詢配額、研究 Provider，或幫我加入模型"></textarea></label><label class="check"><input id="assistant-allow-tests" type="checkbox">這次允許小型推論測試（最多兩次）</label><div class="toolbar"><button id="assistant-stop" type="button" class="ghost" hidden>停止 Assistant</button><button id="assistant-send">執行工作</button></div></form><details><summary>安全輸入 Key</summary><form id="assistant-secret-form"><label>API Base URL<input name="base_url" type="url" required></label><label>名稱<input name="label" maxlength="120" required></label><label>用途<select name="role"><option value="INFERENCE">Inference Key</option><option value="ACCOUNT_PAT">帳戶 PAT</option></select></label><label>Key / PAT<input name="secret" type="password" required autocomplete="off"></label><button>保存安全參照</button></form><p>保存後只把參照交給 Assistant。</p><div id="assistant-secret-list"></div></details><details open><summary>待確認與操作紀錄</summary><div id="assistant-actions" class="cards"></div></details></details>`

const jsAssistant = `
let assistantToolRows=new Map();
let assistantBusy=false,assistantAbort=null,assistantThreads=[],assistantConfigured=null,assistantHistoryVersion=0;
function assistantBubble(role,text){const n=el("div",text,"bubble "+(role==="user"?"user":"assistant"));$("assistant-chat").append(n);$("assistant-chat").scrollTop=$("assistant-chat").scrollHeight;return n;}
function assistantTargets(){const old=$("assistant-target").value;$("assistant-target").replaceChildren();myModels.filter(m=>m.state==="ACTIVE"&&m.enabled&&chatOperation(targetOperation(m))).forEach(m=>option($("assistant-target"),key(m),m.model_id+" · "+connectionLabel(m)));const chosen=assistantConfigured?key(assistantConfigured):old;if([...$("assistant-target").options].some(n=>n.value===chosen))$("assistant-target").value=chosen;}
async function loadAssistant(){if(assistantBusy)return;const [config,threads,actions,refs,reviews]=await Promise.all([api("/assistant/config"),api("/assistant/threads"),api("/assistant/actions"),api("/assistant/secrets"),api("/onboarding")]);assistantConfigured=config.selection||null;assistantThreads=threads;assistantTargets();const old=$("assistant-thread").value;$("assistant-thread").replaceChildren();option($("assistant-thread"),"","新對話");threads.filter(t=>assistantConfigured&&key(t.selection)===key(assistantConfigured)).forEach(t=>option($("assistant-thread"),t.id,t.selection.model_id+" · "+new Date(t.created_at).toLocaleString()));if([...$("assistant-thread").options].some(o=>o.value===old))$("assistant-thread").value=old;const box=$("assistant-actions");box.replaceChildren();reviews.filter(r=>r.status==="REVIEW").forEach(r=>item(box,r.provider.name,"新增連線 · 待確認",()=>openReview(r)));actions.forEach(a=>item(box,a.action,a.state+" · "+new Date(a.at).toLocaleString(),()=>assistantAction(a)));if(!box.children.length)item(box,"還沒有操作","Assistant 準備的變更會出現在這裡。");const secrets=$("assistant-secret-list");secrets.replaceChildren();refs.forEach(ref=>item(secrets,ref.label,ref.base_url+" · "+ref.role,()=>{$("assistant-prompt").value+="\n安全參照 "+ref.id+"（"+ref.label+"）";}));}
async function assistantHistory(){const version=++assistantHistoryVersion,id=$("assistant-thread").value;$("assistant-chat").replaceChildren();if(!id)return;const rows=await api("/assistant/history?thread_id="+encodeURIComponent(id));if(version!==assistantHistoryVersion||id!==$("assistant-thread").value||assistantBusy)return;rows.forEach(r=>{assistantBubble("user",r.message);assistantBubble("assistant",r.result?.text||("工作狀態："+r.status));});}
function assistantAction(a){const box=modal("檢查變更" );box.append(el("p",a.action+" · "+a.state));factsView(box,"變更前",a.before);factsView(box,"變更後",a.after);if(a.state==="PENDING")action(box,"確認此變更",async()=>{notice("正在套用變更…");await submit("/assistant/actions/confirm",{id:a.id,confirm:true});$("detail").close();await refresh();await loadAssistant();notice("變更已套用");},false);if(a.state==="CONFIRMED"&&["CONTROL_CHANGE","ADD_MY_MODEL","REMOVE_MY_MODEL","ACTIVATE_KNOWLEDGE","ACTIVATE_CONNECTOR"].includes(a.action))action(box,"Undo 此變更",async()=>{notice("正在還原變更…");await submit("/assistant/actions/undo",{id:a.id,confirm:true});$("detail").close();await refresh();await loadAssistant();notice("已還原；歷史保留");});}
function assistantBusyState(value){assistantBusy=value;["assistant-target","assistant-thread","assistant-new","assistant-prompt","assistant-send","assistant-allow-tests"].forEach(id=>$(id).disabled=value);$("assistant-config-form").querySelector("button").disabled=value;$("assistant-stop").hidden=!value;}
async function assistantToolResult(payload){let row=assistantToolRows.get(payload.call_id);if(!row){row=item($("assistant-chat"),payload.name,payload.status);if(payload.call_id)assistantToolRows.set(payload.call_id,row);}else row.querySelector("small").textContent=payload.status;if(payload.result){factsView(row,"工具結果",payload.result);if(payload.result.ui_selection&&!busy){await refresh();const selected=key(payload.result.ui_selection);if([...$("target").options].some(n=>n.value===selected)){$("target").value=selected;await refresh();notice("Playground 模型已切換");}}}}
async function assistantSend(e){e.preventDefault();if(assistantBusy)return;const message=$("assistant-prompt").value.trim();if(!message)return;assistantToolRows=new Map();assistantBusyState(true);assistantAbort=new AbortController();const thread_id=$("assistant-thread").value;let currentThread=thread_id,answer=null,done=false;
 try{const resp=await fetch("/api/v1/assistant/run",{method:"POST",credentials:"same-origin",signal:assistantAbort.signal,headers:{"Content-Type":"application/json"},body:JSON.stringify({thread_id,message,allow_tests:$("assistant-allow-tests").checked})});if(!resp.ok||!resp.body)throw Error((await resp.text()).trim());assistantBubble("user",message);$("assistant-prompt").value="";const reader=resp.body.getReader(),decoder=new TextDecoder();let pending="";for(;;){const chunk=await reader.read();pending+=decoder.decode(chunk.value||new Uint8Array(),{stream:!chunk.done});if(pending.length>1048576)throw Error("Assistant 回應超過限制");let i;while((i=pending.indexOf("\n\n"))>=0){const frame=pending.slice(0,i);pending=pending.slice(i+2);const type=frame.split("\n").find(x=>x.startsWith("event:"))?.slice(6).trim(),raw=frame.split("\n").filter(x=>x.startsWith("data:")).map(x=>x.slice(5).trim()).join("\n");if(!type||!raw)continue;const value=JSON.parse(raw);if(type==="thread"){currentThread=value.id;if(![...$("assistant-thread").options].some(n=>n.value===currentThread))option($("assistant-thread"),currentThread,"目前 Assistant 對話");$("assistant-thread").value=currentThread;}if(type==="delta"){if(!answer)answer=assistantBubble("assistant","");answer.textContent+=value.text;}if(type==="tool"){await assistantToolResult(value);answer=null;}if(type==="done"){done=true;notice("Assistant 工作已保存；待確認的變更可在下方檢查");}if(type==="error")throw Error(value.category);}if(chunk.done)break;}if(!done)throw Error("Assistant 串流中斷");
 }catch(err){if(err.name==="AbortError")notice("Assistant 已停止；可查看已保存結果再續聊");else notice("Assistant："+err.message,true);}finally{assistantAbort=null;assistantBusyState(false);await refresh();await loadAssistant();if(currentThread)$("assistant-thread").value=currentThread;}}
function bindAssistant(){$("assistant-panel").addEventListener("toggle",()=>{if($("assistant-panel").open)loadAssistant().catch(e=>notice(e.message,true));});$("assistant-config-form").addEventListener("submit",async e=>{e.preventDefault();try{const selection=JSON.parse($("assistant-target").value);await submit("/assistant/config",{selection});$("assistant-thread").value="";await loadAssistant();notice("Assistant 模型已保存");}catch(e){notice(e.message,true);}});$("assistant-thread").addEventListener("change",()=>assistantHistory().catch(e=>notice(e.message,true)));$("assistant-new").addEventListener("click",()=>{$("assistant-thread").value="";assistantHistoryVersion++;$("assistant-chat").replaceChildren();});$("assistant-form").addEventListener("submit",assistantSend);$("assistant-stop").addEventListener("click",async()=>{try{const thread_id=$("assistant-thread").value;if(thread_id)await submit("/assistant/cancel",{thread_id});}catch(e){}finally{assistantAbort?.abort();}});$("assistant-secret-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.target,button=f.querySelector("button");button.disabled=true;try{const ref=await submit("/assistant/secrets",data(f));f.elements.secret.value="";$("assistant-prompt").value+="\n安全參照 "+ref.id+"（"+ref.label+"）";await loadAssistant();notice("安全參照已保存");}catch(e){notice(e.message,true);}finally{button.disabled=false;}});}
`
